package com.sacco.mvp.accounting.loans;

import com.sacco.mvp.accounting.service.GeneralLedgerService;
import com.sacco.mvp.domain.UserClaim;
import com.sacco.mvp.grouplending.repository.GroupCycleStatementRepository;
import com.sacco.mvp.grouplending.service.*;
import com.sacco.mvp.service.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.transaction.*;
import org.springframework.transaction.support.TransactionTemplate;
import java.math.BigDecimal;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

@EnabledIfEnvironmentVariable(named="MICROFINANCE_RECORDING_TEST_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/microfinance_recording_test")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class GroupCycleStatementPostgresTest {
    final GroupSharedWaiverPostgresTest w=new GroupSharedWaiverPostgresTest();final GroupSharedLoanPostgresTest s=w.s;final LoanRecordingPostgresTest f=w.f;GroupCycleStatementService service;
    static GroupCycleStatementService register(LoanRecordingPostgresTest f){if(!f.context.containsBean("groupCoverageService"))GroupCoveragePostgresTest.register(f);f.context.registerBean(GroupCycleStatementRepository.class,()->new GroupCycleStatementRepository(new NamedParameterJdbcTemplate(f.jdbc)));f.context.registerBean(GroupCycleStatementService.class,()->new GroupCycleStatementService(f.context.getBean(GroupCycleStatementRepository.class),f.context.getBean(GeneralLedgerService.class),f.context.getBean(GroupSharedLoanService.class),f.context.getBean(ApplicationClock.class),new ReportExportLimiter(2),f.context.getBean(GroupCoverageService.class)));return f.context.getBean(GroupCycleStatementService.class);}
    @BeforeAll void start(){w.start();service=register(f);}
    @AfterAll void stop(){w.stop();}
    @BeforeEach void fixture(){w.setup();}
    com.sacco.mvp.grouplending.dto.GroupCycleStatementDtos.Statement read(){return service.statement(f.actor,s.s.cycle,null,null,0,0,0,0,false);}
    TransactionTemplate tx(){var t=new TransactionTemplate(f.context.getBean(PlatformTransactionManager.class));t.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return t;}
    void shadow(String table){
        // These rollback-only fixtures change relation identity; avoid reusing a server plan bound to public before a pg_temp table existed.
        f.jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<Void>) connection->{connection.unwrap(org.postgresql.PGConnection.class).setPrepareThreshold(0);return null;});
        f.jdbc.execute("create temporary table "+table+" on commit drop as select * from public."+table);f.jdbc.execute("set local search_path to pg_temp,public");}
    @Test void sharedParentIsCountedOnceAndVerifiedCashRemainsSeparateFromAllocations(){
        var first=read();assertThat(first.loans()).hasSize(1);assertThat(first.allocations()).hasSize(2);assertThat(first.allocations().stream().map(x->x.principal()).reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo("1000.01");assertThat(first.totals().agreed()).isEqualByComparingTo("1000.01");assertThat(first.totals().principal()).isEqualByComparingTo("1000.01");assertThat(first.totals().dueInterest()).isEqualByComparingTo("20.00");assertThat(first.totals().outstanding()).isEqualByComparingTo("1020.01");f.service.repay(f.actor,w.datedPayment("120.00"));var paid=read();assertThat(paid.loans()).hasSize(1);assertThat(paid.totals().principal()).isEqualByComparingTo("900.01");assertThat(paid.movements()).hasSize(2).anySatisfy(x->{assertThat(x.kind()).isEqualTo("PAYMENT");assertThat(x.cash()).isEqualByComparingTo("120.00");assertThat(x.principal()).isEqualByComparingTo("100.00");assertThat(x.interest()).isEqualByComparingTo("20.00");assertThat(x.payer()).contains("Synthetic member A");});
    }
    @Test void datedActivityDoesNotRepriceBalancesAndWaiversAreNotCash(){w.waive("1.01");var all=read();var filtered=service.statement(f.actor,s.s.cycle,w.date,w.date,0,0,0,0,false);assertThat(filtered.totals()).isEqualTo(all.totals());assertThat(filtered.movements()).singleElement().satisfies(x->{assertThat(x.kind()).isEqualTo("INTEREST_WAIVER");assertThat(x.cash()).isZero();assertThat(x.nonCash()).isEqualByComparingTo("1.01");});assertThat(filtered.totals().dueInterest()).isEqualByComparingTo("18.99");}
    @Test void accountingWriteOffLeavesContractualPrincipalOutstanding(){f.provide(s.loan,"1000.01");var request=f.adjustments().request(f.actor,f.adjustment(s.loan,"WRITE_OFF"));f.adjustments().decide(f.operator("B1"),request,UUID.randomUUID(),true,"Synthetic statement book write-off");var r=read();assertThat(r.totals().principal()).isEqualByComparingTo("1000.01");assertThat(r.movements()).anySatisfy(x->{assertThat(x.kind()).isEqualTo("WRITE_OFF");assertThat(x.cash()).isZero();assertThat(x.nonCash()).isEqualByComparingTo("1000.01");});assertThat(s.count("gl_journal")).isEqualTo(3);}
    @Test void unavailableOpeningMakesCombinedMoneyUnavailable(){tx().executeWithoutResult(t->{shadow("loan_ledgers");f.jdbc.update("delete from loan_ledgers where loan_application_id=?",s.loan);var r=read();assertThat(r.totals().unknown()).isEqualTo(1);assertThat(r.totals().principal()).isNull();assertThat(r.totals().outstanding()).isNull();assertThat(r.totals().fundedPrincipal()).isNull();assertThat(r.loans()).singleElement().satisfies(x->{assertThat(x.funded()).isTrue();assertThat(x.known()).isFalse();});});}
    @Test void currentClaimsExportsAndBranchIsolationAreEnforced(){assertThatThrownBy(()->service.statement(f.operator("B2"),s.s.cycle,null,null,0,0,0,0,false)).isInstanceOf(AccessDeniedException.class);var claims=EnumSet.allOf(UserClaim.class);claims.remove(UserClaim.GROUP_LENDING_EXPORT);when(f.context.getBean(UserClaimService.class).effectiveClaims(eq(f.actor.getMemberId()),anyCollection(),anyBoolean())).thenReturn(claims);assertThat(service.canExport(f.actor)).isFalse();assertThatThrownBy(()->service.statement(f.actor,s.s.cycle,null,null,0,0,0,0,true)).isInstanceOf(AccessDeniedException.class);claims=EnumSet.allOf(UserClaim.class);claims.remove(UserClaim.LOAN_REPORTS_VIEW);when(f.context.getBean(UserClaimService.class).effectiveClaims(eq(f.actor.getMemberId()),anyCollection(),anyBoolean())).thenReturn(claims);assertThatThrownBy(this::read).isInstanceOf(AccessDeniedException.class);assertThatThrownBy(()->service.statement(s.s.client,s.s.cycle,null,null,0,0,0,0,false)).isInstanceOf(AccessDeniedException.class);}
    @Test void sharedContributionReceiptCorrectionAndBilingualDocumentsKeepTheSameOneDebt()throws Exception{
        var collections=f.context.getBean(GroupCollectionService.class);var form=new com.sacco.mvp.grouplending.dto.GroupCollectionDtos.Form();form.setEffectiveDate(w.date);form.setMoneyAccountId(f.cash);form.setReference("QA-CYCLE-STMT-"+UUID.randomUUID());form.setRemitter("Synthetic shared treasurer");form.setEvidence("Synthetic verified collection");var row=new com.sacco.mvp.grouplending.dto.GroupCollectionDtos.Row();row.setLoanId(s.loan);row.setPayerId(f.client);row.setAmount(new BigDecimal("120.00"));row.setDescription("Synthetic member contribution");form.setRows(new ArrayList<>(List.of(row)));form.setPreviewHash(collections.preview(f.actor,s.s.cycle,form).hash());var receipt=collections.post(f.actor,s.s.cycle,form);var paid=read();assertThat(paid.totals().principal()).isEqualByComparingTo("900.01");assertThat(paid.movements()).filteredOn(x->x.kind().equals("PAYMENT")).singleElement().satisfies(x->{assertThat(x.reference()).isEqualTo(receipt.header().number());assertThat(x.cash()).isEqualByComparingTo("120.00");});assertThat(paid.contributions()).hasSize(2);assertThat(paid.contributions().stream().map(x->x.amount()).reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo("120.00");assertThat(paid.allocations().stream().map(x->x.remainingPrincipal()).reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo("900.01");
        var messages=new org.springframework.context.support.ReloadableResourceBundleMessageSource();messages.setBasename("classpath:messages");messages.setDefaultEncoding("UTF-8");messages.setFallbackToSystemLocale(false);var pdf=new GroupCycleStatementPdf(new com.sacco.mvp.accounting.loans.service.LoanRecordingPdfService(new ReportExportLimiter(1)),messages);var exported=service.statement(f.actor,s.s.cycle,null,null,0,0,0,0,true);
        for(var locale:List.of(Locale.ENGLISH,Locale.forLanguageTag("sw"))){byte[] bytes=pdf.render(exported,locale);try(var document=org.apache.pdfbox.Loader.loadPDF(bytes)){var text=new org.apache.pdfbox.text.PDFTextStripper().getText(document).replaceAll("\\s+","");assertThat(text).contains(receipt.header().number(),"900.01").doesNotContain("cycleStatement.","null");}java.nio.file.Files.write(java.nio.file.Path.of("target/group-cycle-statement-"+locale.getLanguage()+".pdf"),bytes);}
        collections.reverse(f.operator("B1"),receipt.header().id(),UUID.randomUUID(),w.date,"Synthetic cycle statement receipt correction");var corrected=read();assertThat(corrected.totals().principal()).isEqualByComparingTo("1000.01");assertThat(corrected.contributions()).hasSize(4).anySatisfy(x->assertThat(x.reversal()).isTrue());assertThat(corrected.movements()).anySatisfy(x->{assertThat(x.kind()).isEqualTo("REVERSAL");assertThat(x.reverses()).isNotBlank();});java.nio.file.Files.writeString(java.nio.file.Path.of("target/group-cycle-statement-fixture.json"),"{\"institution\":\""+f.institution+"\",\"actor\":\""+f.actor.getMemberId()+"\",\"cycle\":\""+s.s.cycle+"\",\"loan\":\""+s.loan+"\"}");
    }
    @Test void realReceiptHistoryPagesWithoutDuplicatingCashOrChangingTheBalanceSnapshot()throws Exception{
        var collections=f.context.getBean(GroupCollectionService.class);for(int n=0;n<26;n++){var form=new com.sacco.mvp.grouplending.dto.GroupCollectionDtos.Form();form.setEffectiveDate(w.date);form.setMoneyAccountId(f.cash);form.setReference("QA-CYCLE-PAGE-"+UUID.randomUUID());form.setRemitter("Synthetic verified group treasurer");form.setEvidence("Synthetic verified one-cent receipt");var row=new com.sacco.mvp.grouplending.dto.GroupCollectionDtos.Row();row.setLoanId(s.loan);row.setPayerId(f.client);row.setAmount(new BigDecimal("0.01"));row.setDescription("Synthetic verified contribution");form.setRows(new ArrayList<>(List.of(row)));form.setPreviewHash(collections.preview(f.actor,s.s.cycle,form).hash());collections.post(f.actor,s.s.cycle,form);}
        var first=read();var second=service.statement(f.actor,s.s.cycle,null,null,0,1,1,0,false);assertThat(first.movements()).hasSize(25);assertThat(first.moreMovements()).isTrue();assertThat(first.contributions()).hasSize(25);assertThat(first.moreContributions()).isTrue();assertThat(second.movements()).hasSize(2);assertThat(second.contributions()).hasSize(1);assertThat(second.totals()).isEqualTo(first.totals());assertThat(first.totals().principal()).isEqualByComparingTo("1000.01");assertThat(first.totals().dueInterest()).isEqualByComparingTo("19.74");assertThat(first.movements().stream().map(x->x.id()).toList()).doesNotContainAnyElementsOf(second.movements().stream().map(x->x.id()).toList());var exported=service.statement(f.actor,s.s.cycle,null,null,0,0,0,0,true);assertThat(exported.contributions().stream().map(x->x.amount()).reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo("0.26");assertThat(s.count("gl_journal")).isEqualTo(27);java.nio.file.Files.writeString(java.nio.file.Path.of("target/group-cycle-statement-page-fixture.json"),"{\"institution\":\""+f.institution+"\",\"actor\":\""+f.actor.getMemberId()+"\",\"cycle\":\""+s.s.cycle+"\",\"loan\":\""+s.loan+"\"}");
    }
    @Test void largeActivityUsesPagingAndRejectsSilentExportTruncation(){tx().executeWithoutResult(t->{shadow("accountant_loan_movement");f.jdbc.update("insert into accountant_loan_movement select (jsonb_populate_record(null::accountant_loan_movement,to_jsonb(p)||jsonb_build_object('id',gen_random_uuid()))).* from public.accountant_loan_movement p cross join generate_series(1,5001) n where p.loan_id=?",s.loan);f.jdbc.execute("create index on accountant_loan_movement(id)");f.jdbc.execute("create index on accountant_loan_movement(loan_id,effective_date,recorded_at,id)");assertThat(f.jdbc.queryForObject("select count(*) from accountant_loan_movement where loan_id=?",Long.class,s.loan)).isEqualTo(5002L);assertThat(read().movements()).hasSize(25);assertThat(read().moreMovements()).isTrue();assertThat(service.statement(f.actor,s.s.cycle,null,null,0,1,0,0,false).movements()).hasSize(25);assertThatThrownBy(()->service.statement(f.actor,s.s.cycle,null,null,0,0,0,0,true)).hasMessage("group.error.statementRange");t.setRollbackOnly();});}
}
